mkitem!{mkstruct!{# [doc = " `CurrentDepGraph` stores the dependency graph for the current session. It"] # [doc = " will be populated as we run queries or tasks. We never remove nodes from the"] # [doc = " graph: they are only added."] # [doc = ""] # [doc = " The nodes in it are identified by a `DepNodeIndex`. We avoid keeping the nodes"] # [doc = " in memory. This is important, because these graph structures are some of the"] # [doc = " largest in the compiler."] # [doc = ""] # [doc = " For this reason, we avoid storing `DepNode`s more than once as map"] # [doc = " keys. The `anon_node_to_index` map only contains nodes of anonymous queries not in the previous"] # [doc = " graph, and we map nodes in the previous graph to indices via a two-step"] # [doc = " mapping. `SerializedDepGraph` maps from `DepNode` to `SerializedDepNodeIndex`,"] # [doc = " and the `prev_index_to_index` vector (which is more compact and faster than"] # [doc = " using a map) maps from `SerializedDepNodeIndex` to `DepNodeIndex`."] # [doc = ""] # [doc = " This struct uses three locks internally. The `data`, `anon_node_to_index`,"] # [doc = " and `prev_index_to_index` fields are locked separately. Operations that take"] # [doc = " a `DepNodeIndex` typically just access the `data` field."] # [doc = ""] # [doc = " We only need to manipulate at most two locks simultaneously:"] # [doc = " `anon_node_to_index` and `data`, or `prev_index_to_index` and `data`. When"] # [doc = " manipulating both, we acquire `anon_node_to_index` or `prev_index_to_index`"] # [doc = " first, and `data` second."] pub (super) struct CurrentDepGraph < D : Deps > { encoder : GraphEncoder < D > , anon_node_to_index : ShardedHashMap < DepNode , DepNodeIndex > , # [doc = " This is used to verify that fingerprints do not change between the creation of a node"] # [doc = " and its recomputation."] # [cfg (debug_assertions)] fingerprints : Lock < IndexVec < DepNodeIndex , Option < Fingerprint > > > , # [doc = " Used to trap when a specific edge is added to the graph."] # [doc = " This is used for debug purposes and is only active with `debug_assertions`."] # [cfg (debug_assertions)] forbidden_edge : Option < EdgeFilter > , # [doc = " Used to verify the absence of hash collisions among DepNodes."] # [doc = " This field is only `Some` if the `-Z incremental_verify_ich` option is present"] # [doc = " or if `debug_assertions` are enabled."] # [doc = ""] # [doc = " The map contains all DepNodes that have been allocated in the current session so far."] nodes_in_current_session : Option < Lock < FxHashMap < DepNode , DepNodeIndex > > > , # [doc = " Anonymous `DepNode`s are nodes whose IDs we compute from the list of"] # [doc = " their edges. This has the beneficial side-effect that multiple anonymous"] # [doc = " nodes can be coalesced into one without changing the semantics of the"] # [doc = " dependency graph. However, the merging of nodes can lead to a subtle"] # [doc = " problem during red-green marking: The color of an anonymous node from"] # [doc = " the current session might \"shadow\" the color of the node with the same"] # [doc = " ID from the previous session. In order to side-step this problem, we make"] # [doc = " sure that anonymous `NodeId`s allocated in different sessions don't overlap."] # [doc = " This is implemented by mixing a session-key into the ID fingerprint of"] # [doc = " each anon node. The session-key is a hash of the number of previous sessions."] anon_id_seed : Fingerprint , # [doc = " These are simple counters that are for profiling and"] # [doc = " debugging and only active with `debug_assertions`."] pub (super) total_read_count : AtomicU64 , pub (super) total_duplicate_read_count : AtomicU64 , }}}
